ALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS hospital_id uuid REFERENCES public.hospitals(id); UPDATE public.audit_logs a SET hospital_id = p.hospital_id FROM public.profiles p WHERE a.hospital_id IS NULL AND p.user_id = a.user_id AND p.hospital_id IS NOT NULL; CREATE INDEX IF NOT EXISTS idx_audit_logs_hospital_id ON public.audit_logs(hospital_id); DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.audit_logs WHERE hospital_id IS NULL) THEN ALTER TABLE public.audit_logs ALTER COLUMN hospital_id SET NOT NULL; END IF; END $do$; DROP POLICY IF EXISTS "Hospital staff can view activity logs" ON public.activity_logs; CREATE POLICY "Admins can view hospital activity logs" ON public.activity_logs FOR SELECT TO authenticated USING ( hospital_id = (SELECT hospital_id FROM profiles WHERE user_id = auth.uid()) AND public.has_role(auth.uid(), 'admin') ); DROP POLICY IF EXISTS "Staff can view own activity logs" ON public.activity_logs; CREATE POLICY "Staff can view own activity logs" ON public.activity_logs FOR SELECT TO authenticated USING ( user_id = auth.uid() AND NOT public.has_role(auth.uid(), 'admin') ); ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS two_factor_required boolean NOT NULL DEFAULT false; COMMENT ON COLUMN public.profiles.two_factor_required IS 'Server-set: true when the user holds a privileged role (admin/doctor). The app blocks access until two_factor_enabled = true.'; CREATE OR REPLACE FUNCTION public.role_requires_2fa(p_role text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $fn$ SELECT p_role IN ('admin', 'doctor') $fn$; CREATE OR REPLACE FUNCTION public.recompute_two_factor_required(p_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN UPDATE public.profiles p SET two_factor_required = EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = p_user_id AND public.role_requires_2fa(ur.role::text) ) WHERE p.user_id = p_user_id; END; $fn$; CREATE OR REPLACE FUNCTION public.sync_two_factor_required() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN IF (TG_OP = 'DELETE') THEN PERFORM public.recompute_two_factor_required(OLD.user_id); RETURN OLD; END IF; PERFORM public.recompute_two_factor_required(NEW.user_id); IF (TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id) THEN PERFORM public.recompute_two_factor_required(OLD.user_id); END IF; RETURN NEW; END; $fn$; DROP TRIGGER IF EXISTS trg_sync_two_factor_required ON public.user_roles; CREATE TRIGGER trg_sync_two_factor_required AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.sync_two_factor_required(); UPDATE public.profiles p SET two_factor_required = EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = p.user_id AND public.role_requires_2fa(ur.role::text) ); ALTER TABLE public.prescription_items ADD COLUMN IF NOT EXISTS hospital_id uuid REFERENCES public.hospitals(id) ON DELETE CASCADE; UPDATE public.prescription_items pi SET hospital_id = p.hospital_id FROM public.prescriptions p WHERE p.id = pi.prescription_id AND pi.hospital_id IS NULL; CREATE OR REPLACE FUNCTION public.set_prescription_item_hospital_id() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN IF NEW.hospital_id IS NULL THEN SELECT hospital_id INTO NEW.hospital_id FROM public.prescriptions WHERE id = NEW.prescription_id; END IF; RETURN NEW; END; $fn$; DROP TRIGGER IF EXISTS trg_set_prescription_item_hospital_id ON public.prescription_items; CREATE TRIGGER trg_set_prescription_item_hospital_id BEFORE INSERT OR UPDATE ON public.prescription_items FOR EACH ROW EXECUTE FUNCTION public.set_prescription_item_hospital_id(); ALTER TABLE public.prescription_items ALTER COLUMN hospital_id SET NOT NULL; CREATE INDEX IF NOT EXISTS idx_prescription_items_hospital_id ON public.prescription_items(hospital_id); DROP POLICY IF EXISTS "prescription_items_hospital_isolation" ON public.prescription_items; CREATE POLICY "prescription_items_hospital_isolation" ON public.prescription_items FOR ALL TO authenticated USING (hospital_id = (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid())) WITH CHECK (hospital_id = (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid())); CREATE OR REPLACE FUNCTION public.prevent_activity_log_mutation() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN RAISE EXCEPTION 'activity_logs is append-only: % is not permitted', TG_OP USING ERRCODE = 'insufficient_privilege'; END; $fn$; DROP TRIGGER IF EXISTS trg_activity_logs_immutable ON public.activity_logs; CREATE TRIGGER trg_activity_logs_immutable BEFORE UPDATE OR DELETE ON public.activity_logs FOR EACH ROW EXECUTE FUNCTION public.prevent_activity_log_mutation(); DROP POLICY IF EXISTS "activity_logs_no_update" ON public.activity_logs; CREATE POLICY "activity_logs_no_update" ON public.activity_logs FOR UPDATE TO authenticated USING (false) WITH CHECK (false); DROP POLICY IF EXISTS "activity_logs_no_delete" ON public.activity_logs; CREATE POLICY "activity_logs_no_delete" ON public.activity_logs FOR DELETE TO authenticated USING (false); ALTER TABLE appointments ADD COLUMN IF NOT EXISTS doctor_id UUID REFERENCES profiles(id); ALTER TABLE appointments ADD COLUMN IF NOT EXISTS appointment_date DATE; ALTER TABLE vital_signs ADD COLUMN IF NOT EXISTS pulse INTEGER; ALTER TABLE lab_results ADD COLUMN IF NOT EXISTS lab_result TEXT; ALTER TABLE prescription_refill_requests ADD COLUMN IF NOT EXISTS prescription_id UUID REFERENCES prescriptions(id); CREATE INDEX IF NOT EXISTS idx_appointments_doctor_id ON appointments(doctor_id); CREATE INDEX IF NOT EXISTS idx_appointments_appointment_date ON appointments(appointment_date); CREATE INDEX IF NOT EXISTS idx_vital_signs_pulse ON vital_signs(pulse); CREATE INDEX IF NOT EXISTS idx_lab_results_lab_result ON lab_results(lab_result); CREATE TABLE IF NOT EXISTS public.system_metrics ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE, ai_calls_count INTEGER DEFAULT 0, ai_tokens_used INTEGER DEFAULT 0, ai_cost_estimate DECIMAL(10, 4) DEFAULT 0.00, ai_model VARCHAR(100), ai_feature VARCHAR(100), response_time_ms INTEGER, memory_usage_mb DECIMAL(10, 2), measured_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(), created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), notes TEXT ); CREATE INDEX IF NOT EXISTS idx_system_metrics_hospital_measured ON system_metrics(hospital_id, measured_at DESC); CREATE INDEX IF NOT EXISTS idx_system_metrics_ai_calls ON system_metrics(hospital_id, ai_calls_count DESC) WHERE ai_calls_count > 0; CREATE INDEX IF NOT EXISTS idx_system_metrics_cost ON system_metrics(hospital_id, ai_cost_estimate DESC) WHERE ai_cost_estimate > 0; ALTER TABLE system_metrics ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Admins can view hospital metrics" ON system_metrics; CREATE POLICY "Admins can view hospital metrics" ON system_metrics FOR SELECT USING ( hospital_id = (SELECT hospital_id FROM user_roles WHERE user_id = auth.uid() LIMIT 1) AND EXISTS ( SELECT 1 FROM user_roles WHERE user_id = auth.uid() AND hospital_id = system_metrics.hospital_id AND role = 'admin' ) ); DROP POLICY IF EXISTS "Admins can insert metrics" ON system_metrics; CREATE POLICY "Admins can insert metrics" ON system_metrics FOR INSERT WITH CHECK ( hospital_id = (SELECT hospital_id FROM user_roles WHERE user_id = auth.uid() LIMIT 1) AND EXISTS ( SELECT 1 FROM user_roles WHERE user_id = auth.uid() AND hospital_id = system_metrics.hospital_id AND role = 'admin' ) ); GRANT SELECT, INSERT ON system_metrics TO authenticated; GRANT ALL ON system_metrics TO service_role; COMMENT ON TABLE system_metrics IS 'Tracks system health metrics including AI usage, costs, and performance indicators - Tier 3.2 Observability';